{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"user message text"}
{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user_tool_result","ts":"...","tool_use_id":"toolu_xxx","result":{"type":"text","file":"path"}}
{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[{"type":"text","text":"..."},{"type":"tool_use","id":"toolu_xxx","name":"Read","input":{...}}]}

