import json, sys

expected_user = {'v', 'agent', 'cli_version', 'type', 'ts', 'content'}
expected_assistant = {'v', 'agent', 'cli_version', 'type', 'ts', 'id', 'content'}
expected_tool_result = {'v', 'agent', 'cli_version', 'type', 'ts', 'tool_use_id', 'result'}

issues = []
with open('transcript-output.jsonl') as f:
    for i, line in enumerate(f, 1):
        line = line.strip()
        if not line:
            continue
        obj = json.loads(line)
        t = obj.get('type')
        keys = set(obj.keys())

        if t == 'user':
            missing = expected_user - keys
            extra = keys - expected_user
            if missing:
                issues.append(f'Line {i}: user missing {missing}')
            if extra:
                issues.append(f'Line {i}: user extra {extra}')
        elif t == 'assistant':
            missing = expected_assistant - keys
            extra = keys - expected_assistant
            if missing:
                issues.append(f'Line {i}: assistant missing {missing}')
            if extra:
                issues.append(f'Line {i}: assistant extra {extra}')
        elif t == 'user_tool_result':
            missing = expected_tool_result - keys
            extra = keys - expected_tool_result
            if missing:
                issues.append(f'Line {i}: user_tool_result missing {missing}')
            if extra:
                issues.append(f'Line {i}: user_tool_result extra {extra}')
        else:
            issues.append(f'Line {i}: unknown type {t!r}')

if issues:
    for iss in issues:
        print(iss)
else:
    print('All lines match expected schema')
" 2>&1

